with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'شبكات الرصد الجوي وإدارة البيانات وضمان الجودة','تخطيط شبكات المحطات والرصد العلوي والبحري والراداري، وصيانة الأجهزة وضبط جودة البيانات وإدارتها وتبادلها.',32,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تصميم وتشغيل شبكات الرصد',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'جودة البيانات والأرشفة والتكامل',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('surface-weather-station-network-design','تصميم شبكة محطات الرصد السطحي','توزيع المحطات وفق التضاريس والأهداف والمعايير.','{"blocks":[{"type":"text","text":"يعرض الدرس تصميم شبكة محطات الرصد السطحي بوصفه جزءاً من منظومة الرصد الوطنية التي توفر بيانات موثوقة للتحليل والتنبؤ والمناخ."},{"type":"text","text":"المبدأ الأساسي: توزيع المحطات وفق التضاريس والأهداف والمعايير.، ويرتبط تصميم النظام بهدف الرصد والموقع والبيئة ومتطلبات المستخدم."},{"type":"text","text":"يحدد تصميم العمل المتغيرات المطلوبة ودقة القياس ومعدل أخذ العينات وفترة الإتاحة."},{"type":"text","text":"توثق مواصفات الأجهزة ومواقعها وارتفاعات الحساسات والوحدات وتاريخ المعايرة والتغييرات."},{"type":"text","text":"تطبق فحوص الجودة الأولية لاكتشاف القيم خارج المدى والانقطاعات والتغيرات المفاجئة والاتساق بين المتغيرات."},{"type":"text","text":"تراجع البيانات مكانياً بمقارنتها بمحطات مجاورة أو منتجات مستقلة مع مراعاة اختلاف الارتفاع والتضاريس."},{"type":"text","text":"تراجع السجلات زمنياً للكشف عن الانجراف والانقطاع وتغير الأجهزة أو بيئة المحطة."},{"type":"text","text":"يجب الحفاظ على القيمة الخام والاحتفاظ بسجل منفصل للقيمة المصححة أو المستبعدة وسبب الإجراء."},{"type":"text","text":"تستخدم معرفات ثابتة للمحطات والمتغيرات والوحدات مع توحيد التوقيت والتقويم والإحداثيات."},{"type":"text","text":"تحدد اتفاقيات التبادل وصيغ البيانات وواجهات الخدمات بما يضمن التكامل وقابلية التوسع."},{"type":"text","text":"مثال تطبيقي: يمر سجل محطة من الاستقبال إلى فحص الجودة ثم التخزين مع حفظ وقت الوصول والمصدر وعلامة الجودة."},{"type":"callout","text":"الخلاصة: شبكة الرصد الجيدة ليست أجهزة فقط؛ بل تشغيل وصيانة وبيانات موثقة وجودة واتصال مستمر."}]}',2760,55,'["شرح مكونات النظام أو الإجراء","تطبيق فحوص الجودة والتوثيق","تحديد متطلبات التكامل والاستمرارية"]','تصميم وتشغيل شبكات الرصد'),
('automatic-weather-station-sensors','حساسات محطات الطقس الآلية ومبادئ القياس','الحرارة والرطوبة والضغط والرياح والهطول والإشعاع.','{"blocks":[{"type":"text","text":"يعرض الدرس حساسات محطات الطقس الآلية ومبادئ القياس بوصفه جزءاً من منظومة الرصد الوطنية التي توفر بيانات موثوقة للتحليل والتنبؤ والمناخ."},{"type":"text","text":"المبدأ الأساسي: الحرارة والرطوبة والضغط والرياح والهطول والإشعاع.، ويرتبط تصميم النظام بهدف الرصد والموقع والبيئة ومتطلبات المستخدم."},{"type":"text","text":"يحدد تصميم العمل المتغيرات المطلوبة ودقة القياس ومعدل أخذ العينات وفترة الإتاحة."},{"type":"text","text":"توثق مواصفات الأجهزة ومواقعها وارتفاعات الحساسات والوحدات وتاريخ المعايرة والتغييرات."},{"type":"text","text":"تطبق فحوص الجودة الأولية لاكتشاف القيم خارج المدى والانقطاعات والتغيرات المفاجئة والاتساق بين المتغيرات."},{"type":"text","text":"تراجع البيانات مكانياً بمقارنتها بمحطات مجاورة أو منتجات مستقلة مع مراعاة اختلاف الارتفاع والتضاريس."},{"type":"text","text":"تراجع السجلات زمنياً للكشف عن الانجراف والانقطاع وتغير الأجهزة أو بيئة المحطة."},{"type":"text","text":"يجب الحفاظ على القيمة الخام والاحتفاظ بسجل منفصل للقيمة المصححة أو المستبعدة وسبب الإجراء."},{"type":"text","text":"تستخدم معرفات ثابتة للمحطات والمتغيرات والوحدات مع توحيد التوقيت والتقويم والإحداثيات."},{"type":"text","text":"تحدد اتفاقيات التبادل وصيغ البيانات وواجهات الخدمات بما يضمن التكامل وقابلية التوسع."},{"type":"text","text":"مثال تطبيقي: يمر سجل محطة من الاستقبال إلى فحص الجودة ثم التخزين مع حفظ وقت الوصول والمصدر وعلامة الجودة."},{"type":"callout","text":"الخلاصة: شبكة الرصد الجيدة ليست أجهزة فقط؛ بل تشغيل وصيانة وبيانات موثقة وجودة واتصال مستمر."}]}',2770,55,'["شرح مكونات النظام أو الإجراء","تطبيق فحوص الجودة والتوثيق","تحديد متطلبات التكامل والاستمرارية"]','تصميم وتشغيل شبكات الرصد'),
('station-siting-and-exposure','اختيار موقع المحطة والتعرض الرصدي','أثر العوائق والارتفاع والسطوح المحيطة على القياس.','{"blocks":[{"type":"text","text":"يعرض الدرس اختيار موقع المحطة والتعرض الرصدي بوصفه جزءاً من منظومة الرصد الوطنية التي توفر بيانات موثوقة للتحليل والتنبؤ والمناخ."},{"type":"text","text":"المبدأ الأساسي: أثر العوائق والارتفاع والسطوح المحيطة على القياس.، ويرتبط تصميم النظام بهدف الرصد والموقع والبيئة ومتطلبات المستخدم."},{"type":"text","text":"يحدد تصميم العمل المتغيرات المطلوبة ودقة القياس ومعدل أخذ العينات وفترة الإتاحة."},{"type":"text","text":"توثق مواصفات الأجهزة ومواقعها وارتفاعات الحساسات والوحدات وتاريخ المعايرة والتغييرات."},{"type":"text","text":"تطبق فحوص الجودة الأولية لاكتشاف القيم خارج المدى والانقطاعات والتغيرات المفاجئة والاتساق بين المتغيرات."},{"type":"text","text":"تراجع البيانات مكانياً بمقارنتها بمحطات مجاورة أو منتجات مستقلة مع مراعاة اختلاف الارتفاع والتضاريس."},{"type":"text","text":"تراجع السجلات زمنياً للكشف عن الانجراف والانقطاع وتغير الأجهزة أو بيئة المحطة."},{"type":"text","text":"يجب الحفاظ على القيمة الخام والاحتفاظ بسجل منفصل للقيمة المصححة أو المستبعدة وسبب الإجراء."},{"type":"text","text":"تستخدم معرفات ثابتة للمحطات والمتغيرات والوحدات مع توحيد التوقيت والتقويم والإحداثيات."},{"type":"text","text":"تحدد اتفاقيات التبادل وصيغ البيانات وواجهات الخدمات بما يضمن التكامل وقابلية التوسع."},{"type":"text","text":"مثال تطبيقي: يمر سجل محطة من الاستقبال إلى فحص الجودة ثم التخزين مع حفظ وقت الوصول والمصدر وعلامة الجودة."},{"type":"callout","text":"الخلاصة: شبكة الرصد الجيدة ليست أجهزة فقط؛ بل تشغيل وصيانة وبيانات موثقة وجودة واتصال مستمر."}]}',2780,55,'["شرح مكونات النظام أو الإجراء","تطبيق فحوص الجودة والتوثيق","تحديد متطلبات التكامل والاستمرارية"]','تصميم وتشغيل شبكات الرصد'),
